"""The rule a status board obeys, whichever repository prints it.

Each repository of the family prints one document a reader is told to trust
without reading the code: `docs/harness-status.md` in the corpus, `docs/status.md`
in the library and in the server. Their contents differ, and must - one holds a
corpus, one holds treaties, one holds answers. The rule does not differ:

  * exactly one document says which command writes it, and says that it is not
    to be edited by hand;
  * it names the project, taken from `pyproject.toml`, and never the directory
    the checkout happens to live in - so a clone called anything at all produces
    the same document;
  * a test holds the committed file against the command's own output, so a hand
    edit is a red run rather than a number nobody can trace;
  * CI runs the tests, or the third rule holds nothing.

Nothing here renders a board: rendering belongs to the repository, and the rule
does not. That is why the three copies of it could drift for so long unnoticed -
each one was a paragraph of prose in a test file and a convention in a script -
and why it is shared code from here on, vendored with the rest of the discipline.
"""
from __future__ import annotations

import re
from pathlib import Path

from . import ci, machine_traces

# The declaration every board makes in its own words, but in these two: the
# command that writes it, in backticks, and the sentence that refuses an edit.
GENERATOR = re.compile(r"Generated by `([^`]+)`")
NO_EDITS = "Do not edit by hand"
PROJECT_LINE = re.compile(r"^- project: `([^`]+)`", re.M)


def documents(root: Path) -> list[Path]:
    """The generated documents of this repository, in name order.

    Found rather than named: a repository that moved its board and left the rule
    pointing at the old path would be a check about a file nobody reads.
    """
    out: list[Path] = []
    for path in sorted((root / "docs").glob("*.md")):
        text = path.read_text(encoding="utf-8", errors="replace")
        if NO_EDITS in text and GENERATOR.search(text):
            out.append(path)
    return out


def _command(text: str) -> str | None:
    found = GENERATOR.search(text)
    return found.group(1) if found else None


def current_test(root: Path, board: Path, command: str) -> Path | None:
    """The test that holds this board against the command's own output.

    A test that names both the board and the command that writes it: the rule is
    "a generated document is the command's output", and a test that mentioned
    neither would be about something else.
    """
    relative = board.relative_to(root).as_posix()
    for path in sorted((root / "tests").glob("*.py")):
        text = path.read_text(encoding="utf-8", errors="replace")
        if relative in text and command in text:
            return path
    return None


def facts(root: Path, project: str | None = None) -> dict:
    """What the board rule amounts to in this repository, for a comparison.

    The paths are this repository's own business; the four booleans are the rule,
    and `scripts/discipline-drift.py` requires them of all three.
    """
    found = documents(root)
    board = found[0] if len(found) == 1 else None
    text = board.read_text(encoding="utf-8", errors="replace") if board else ""
    command = _command(text) if board else None
    name = project if project is not None else machine_traces.project_name(root)
    named = PROJECT_LINE.search(text)
    return {
        "board": board.relative_to(root).as_posix() if board else None,
        "documents": len(found),
        "command": command,
        "project": name,
        "names_the_project": bool(named and named.group(1) == name),
        "current_test": (current_test(root, board, command).relative_to(root).as_posix()
                         if board and command and current_test(root, board, command)
                         else None),
        "run_in_ci": ci.runs_pytest(root),
    }


def problems(root: Path, project: str | None = None) -> list[str]:
    """Every way this repository's board breaks the rule, named."""
    found = facts(root, project)
    out: list[str] = []
    if found["documents"] != 1:
        out.append(f"{found['documents']} generated documents under docs/, and "
                   f"the rule is one: {found['board']}")
    if not found["command"]:
        out.append("the board does not say which command writes it")
    if not found["names_the_project"]:
        out.append(f"the board does not print `- project: `{found['project']}` "
                   f"from pyproject.toml")
    if not found["current_test"]:
        out.append("no test names both the board and the command that writes it, "
                   "so nothing holds the committed file against the command")
    if not found["run_in_ci"]:
        out.append("no workflow step runs pytest, so the test above holds nothing")
    return out
